// 301 redirect the retired /recycling-eu/ page to the InnoCycle site.
if ( ! empty( $_SERVER['REQUEST_URI'] ) ) {
	$p = strtok( $_SERVER['REQUEST_URI'], '?' );
	if ( in_array( rtrim( $p, '/' ), array( '/recycling-eu', '/es/recycling-eu' ), true ) ) {
		header( 'Location: https://www.innocycle.com/', true, 301 );
		exit;
	}
}
